package it.gerio.platform.common;

import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.MappedSuperclass;

/**
 * Numeric id generated by the database (ADR-0003).
 *
 * <p>Extends {@code PanacheEntityBase} (through {@link AuditedEntity}), not {@code PanacheEntity}:
 * the latter generates ids with a sequence, while our tables use {@code generated always as
 * identity}, and Postgres rejects an insert that supplies the id itself.
 */
@MappedSuperclass
public abstract class EntityBase extends AuditedEntity {

  @Id
  @GeneratedValue(strategy = GenerationType.IDENTITY)
  private Long id;

  public Long getId() {
    return id;
  }
}
